## Widget Test：测试组件行为

Widget Test 是 Flutter 测试金字塔中投入产出比最高的层级：

```dart
// test/presentation/widgets/product_card_test.dart
void main() {
  group('ProductCard', () {
    testWidgets('renders product name and price', (tester) async {
      const product = Product(
        id: '1',
        name: 'Flutter Cookbook',
        price: 39.99,
        imageUrl: 'https://example.com/book.jpg',
      );

      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: ProductCard(product: product),
          ),
        ),
      );

      // 查找 Widget
      expect(find.text('Flutter Cookbook'), findsOneWidget);
      expect(find.text('\$39.99'), findsOneWidget);
    });

    testWidgets('calls onAddToCart when button tapped', (tester) async {
      bool addToCartCalled = false;

      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: ProductCard(
              product: testProduct,
              onAddToCart: () => addToCartCalled = true,
            ),
          ),
        ),
      );

      await tester.tap(find.byIcon(Icons.add_shopping_cart));
      await tester.pump();

      expect(addToCartCalled, isTrue);
    });

    testWidgets('shows loading indicator while image loads', (tester) async {
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: ProductCard(product: testProductWithNetworkImage),
          ),
        ),
      );

      // pump() 触发一帧，不等待异步完成
      await tester.pump();
      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      // pumpAndSettle() 等待所有动画和异步完成
      await tester.pumpAndSettle();
      expect(find.byType(CircularProgressIndicator), findsNothing);
    });
  });
}
```

### 测试 Riverpod 状态

```dart
testWidgets('CartPage shows items from Riverpod provider', (tester) async {
  final container = ProviderContainer(
    overrides: [
      cartNotifierProvider.overrideWith(() => FakeCartNotifier()),
    ],
  );

  await tester.pumpWidget(
    UncontrolledProviderScope(
      container: container,
      child: const MaterialApp(home: CartPage()),
    ),
  );

  await tester.pumpAndSettle();
  expect(find.text('Test Product'), findsOneWidget);
});

class FakeCartNotifier extends CartNotifier {
  @override
  List<CartItem> build() => [
    CartItem(id: '1', name: 'Test Product', price: 9.99),
  ];
}
```

